<script>
(() => {
    const app = document.getElementById('exam-app');
    const payload = JSON.parse(app.dataset.payload);
    const questions = payload.questions;
    let current = 0;
    let remaining = Number(payload.remaining_seconds || 0);
    let saveTimer;
    const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
    const answered = (question) => question.answer !== null && question.answer !== '' && !(Array.isArray(question.answer) && question.answer.length === 0);
    const formatTime = (seconds) => `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
    const status = (text, tone = 'muted') => { const el = document.getElementById('save-status'); el.className = `flex items-center gap-2 text-[10px] text-${tone}`; el.innerHTML = `<span class="h-1.5 w-1.5 rounded-full bg-${tone}"></span>${esc(text)}`; };
    const optionButton = (question, option, selected) => `<button type="button" data-choice="${esc(option.key)}" class="option flex min-h-12 w-full items-center gap-3 rounded-lg border ${selected ? 'border-2 border-orange bg-orange/10' : 'border-line bg-[#151515]'} px-3.5 text-left text-sm transition hover:border-orange"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${selected ? 'bg-orange font-bold' : 'border border-line text-muted'} font-mono text-[11px]">${esc(option.key)}</span><span class="${selected ? 'font-medium' : ''}">${esc(option.label)}</span>${selected ? '<iconify-icon icon="lucide:check-circle-2" class="ml-auto text-orange"></iconify-icon>' : ''}</button>`;
    function renderQuestion() {
        const question = questions[current];
        const selected = Array.isArray(question.answer) ? question.answer : [question.answer];
        let body = '';
        if (question.type === 'multiple_choice') body = `<div class="mt-7 space-y-3">${question.options.map((option) => optionButton(question, option, selected.includes(option.key))).join('')}</div>`;
        else if (question.type === 'multiple_select') body = `<div class="mt-7 space-y-3">${question.options.map((option) => optionButton(question, option, selected.includes(option.key).toString().toLowerCase() === 'true')).join('')}</div>`;
        else if (question.type === 'true_false') body = `<div class="mt-7 grid grid-cols-2 gap-3"><button type="button" data-boolean="true" class="option min-h-12 rounded-lg border ${question.answer === true ? 'border-orange bg-orange/10 text-orange' : 'border-line bg-[#151515]'} text-sm">Benar</button><button type="button" data-boolean="false" class="option min-h-12 rounded-lg border ${question.answer === false ? 'border-orange bg-orange/10 text-orange' : 'border-line bg-[#151515]'} text-sm">Salah</button></div>`;
        else if (question.type === 'essay') body = `<textarea id="free-answer" class="cbt-input mt-7 min-h-40 resize-y py-3" placeholder="Tulis jawabanmu...">${esc(question.answer || '')}</textarea>`;
        else body = `<input id="free-answer" class="cbt-input mt-7" value="${esc(question.answer || '')}" placeholder="Tulis jawabanmu...">`;
        document.getElementById('question-card').innerHTML = `<div class="flex flex-wrap items-center gap-2"><span class="rounded bg-orange/15 px-2 py-1 font-mono text-[10px] text-orange">${String(current + 1).padStart(2, '0')} DARI ${questions.length}</span><span class="rounded border border-line px-2 py-1 font-mono text-[9px] text-muted">${esc(question.type.replaceAll('_', ' ').toUpperCase())}</span></div><h1 class="mt-7 max-w-3xl font-serif text-[25px] font-bold leading-[1.35] sm:text-[30px]">${esc(question.prompt)}</h1><p class="mt-3 text-sm text-muted">${question.type === 'multiple_choice' || question.type === 'multiple_select' ? 'Pilih jawaban yang paling tepat.' : 'Tuliskan jawaban dengan jelas.'}</p>${body}`;
        document.getElementById('flag-label').textContent = question.flagged ? 'Hapus tanda' : 'Tandai pertanyaan';
        document.getElementById('previous-button').disabled = current === 0;
        document.getElementById('previous-button').classList.toggle('opacity-40', current === 0);
        document.getElementById('next-button').textContent = current === questions.length - 1 ? 'Selesai' : 'Berikutnya';
        document.getElementById('next-button').insertAdjacentHTML('beforeend', `<iconify-icon icon="lucide:${current === questions.length - 1 ? 'check' : 'arrow-right'}"></iconify-icon>`);
        bindQuestionEvents(question);
        renderGrids();
        updateProgress();
    }
    function bindQuestionEvents(question) {
        document.querySelectorAll('[data-choice]').forEach((button) => button.addEventListener('click', () => {
            if (question.type === 'multiple_select') { const currentAnswer = Array.isArray(question.answer) ? [...question.answer] : []; const key = button.dataset.choice; question.answer = currentAnswer.includes(key) ? currentAnswer.filter((value) => value !== key) : [...currentAnswer, key]; }
            else question.answer = button.dataset.choice;
            renderQuestion(); queueSave(question);
        }));
        document.querySelectorAll('[data-boolean]').forEach((button) => button.addEventListener('click', () => { question.answer = button.dataset.boolean === 'true'; renderQuestion(); queueSave(question); }));
        document.getElementById('free-answer')?.addEventListener('input', (event) => { question.answer = event.target.value; queueSave(question); });
    }
    function queueSave(question) { clearTimeout(saveTimer); status('Menyimpan...', 'muted'); saveTimer = setTimeout(() => save(question), 350); }
    async function save(question) {
        try { const response = await fetch(app.dataset.answerUrl.replace('QUESTION_ID', question.id), { method: 'POST', headers: {'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':app.dataset.csrf}, body: JSON.stringify({answer: question.answer, client_version: question.answer_version || 0}) }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Gagal menyimpan'); question.answer = data.answer; question.answer_version = data.version; status('Tersimpan', 'success'); renderGrids(); } catch (error) { status('Gagal menyimpan · coba lagi', 'error'); }
    }
    async function toggleFlag() { const question = questions[current]; try { const response = await fetch(app.dataset.flagUrl.replace('QUESTION_ID', question.id), {method:'POST', headers:{'Accept':'application/json','X-CSRF-TOKEN':app.dataset.csrf}}); const data = await response.json(); if (!response.ok) throw new Error(); question.flagged = data.flagged; renderQuestion(); } catch (error) { status('Gagal menandai', 'error'); } }
    function renderGrids() { ['desktop-grid', 'mobile-grid'].forEach((id) => { const grid = document.getElementById(id); if (!grid) return; grid.innerHTML = questions.map((question, index) => `<button type="button" data-index="${index}" class="relative h-9 rounded border font-mono text-[10px] ${index === current ? 'border-orange bg-orange text-white' : answered(question) ? 'border-info/50 bg-info/10 text-info' : 'border-line bg-elevated text-muted'}">${index + 1}${question.flagged ? '<iconify-icon icon="lucide:flag" class="absolute -right-1 -top-1 rounded-full bg-[#111111] p-0.5 text-[9px] text-orange"></iconify-icon>' : ''}</button>`).join(''); grid.querySelectorAll('[data-index]').forEach((button) => button.addEventListener('click', () => { current = Number(button.dataset.index); renderQuestion(); closeSheet(); })); }); }
    function updateProgress() { const count = questions.filter(answered).length; document.getElementById('progress-label').textContent = `${count} / ${questions.length}`; document.getElementById('progress-bar').style.width = `${questions.length ? count / questions.length * 100 : 0}%`; }
    function closeSheet() { document.getElementById('mobile-sheet').classList.add('hidden'); document.getElementById('mobile-backdrop').classList.add('hidden'); }
    function confirmSubmit() { const unanswered = questions.filter((question) => !answered(question)).length; return confirm(unanswered ? `Masih ada ${unanswered} soal belum dijawab. Kirim ujian sekarang?` : 'Kirim ujian sekarang?'); }
    document.getElementById('previous-button').addEventListener('click', () => { if (current > 0) { current -= 1; renderQuestion(); } });
    document.getElementById('next-button').addEventListener('click', () => { if (current < questions.length - 1) { current += 1; renderQuestion(); } else document.getElementById('desktop-submit')?.click(); });
    document.getElementById('flag-button').addEventListener('click', toggleFlag); document.getElementById('mobile-flag').addEventListener('click', toggleFlag);
    document.getElementById('open-navigation').addEventListener('click', () => { document.getElementById('mobile-sheet').classList.remove('hidden'); document.getElementById('mobile-backdrop').classList.remove('hidden'); }); document.getElementById('close-navigation').addEventListener('click', closeSheet); document.getElementById('mobile-backdrop').addEventListener('click', closeSheet);
    setInterval(() => { remaining = Math.max(0, remaining - 1); document.getElementById('timer').textContent = formatTime(remaining); if (remaining === 60) document.getElementById('timer').classList.add('text-warning'); }, 1000);
    window.confirmSubmit = confirmSubmit; renderQuestion(); document.getElementById('timer').textContent = formatTime(remaining);
})();
</script>
@endsection
